const body = $input.first().json;
const raw = body?.data?.[0]?.[0];
if (!raw) {
  throw new Error('No result from Snowflake: ' + JSON.stringify(body).slice(0, 500));
}
const result = typeof raw === 'string' ? JSON.parse(raw) : raw;
const exec = result.execution ?? {};
return [{ json: {
  gate: result.gate,
  passed: exec.passed ?? 0,
  failed: exec.failed ?? 0,
  errored: exec.errored ?? 0,
  sfHost: $('Config').first().json.sfHost
}}];

const body = $input.first().json;
const raw = body?.data?.[0]?.[0];
const result = typeof raw === 'string' ? JSON.parse(raw) : raw;
const d = result?.defect ?? {};
const qa = $('Parse QA Result').first().json;

// Severity drives who gets woken up. The taxonomy severity model is the
// authority for this, not a guess in the workflow.
const escalate = ['CRITICAL', 'HIGH'].includes(d.severity);

return [{ json: {
  subject: `[${d.severity ?? 'UNKNOWN'}] AP pipeline data quality failure - ${d.category ?? 'uncategorised'}`,
  escalate,
  defect_id: d.defect_id ?? null,
  category: d.category ?? null,
  severity: d.severity ?? null,
  confidence: d.confidence ?? null,
  tests_failed: qa.failed,
  tests_errored: qa.errored,
  tests_passed: qa.passed,
  body: [
    `Failing tests: ${qa.failed} (errored: ${qa.errored}, passed: ${qa.passed})`,
    `Triaged category: ${d.category}`,
    `Severity: ${d.severity}`,
    `Agent confidence: ${d.confidence}`,
    ``,
    `Root cause and remediation are recorded against defect ${d.defect_id}`,
    `in CAPSTONE_AI_DLC.ARTIFACTS.DEFECTS. The triage is a starting point, not`,
    `a verdict - confirm before acting.`
  ].join('\n')
}}];
